// Obtenemos el valor de 'respuesta_definitiva' desde el input
const respuestaDefinitiva = $('Webhook').first().json.body.custom_fields.respuesta_definitiva || '';

// Función para separar el texto y detectar múltiples enlaces
function separarMensaje(texto) {
    // Si no hay texto, devolvemos valores vacíos
    if (!texto) {
        return {
            texto: '',
            audio: []
        };
    }

    // Expresión regular para detectar URLs
    const urlRegex = /https:\/\/manybot-files\.s3\.eu-central-1\.amazonaws\.com\/[^,\s]+/g;
    const matches = texto.match(urlRegex) || []; // Obtenemos todas las coincidencias

    // Extraemos el texto eliminando los enlaces y comas, y limpiando espacios
    const textoLimpio = texto
        .replace(urlRegex, '') // Eliminamos los enlaces
        .replace(/,/g, '') // Eliminamos comas
        .trim(); // Limpiamos espacios

    return {
        texto: textoLimpio,
        audio: matches
    };
}

// Llamamos a la función y devolvemos el resultado
return separarMensaje(respuestaDefinitiva);

// Devuelve el Mensaje que coincide (contenido parcial o total) con
// $('Webhook').first().json.body.custom_fields.respuesta_definitiva

function limpiarTexto(t) {
  return String(t || '')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

const webhookNode = $('Webhook').first();
const body = webhookNode && webhookNode.json && webhookNode.json.body;
const custom = body && body.custom_fields;
const rawRespuesta = custom && custom.respuesta_definitiva;

if (!rawRespuesta) {
  return [{ json: { resultado: null, motivo: 'No hay respuesta_definitiva' } }];
}

const resp = limpiarTexto(rawRespuesta);

// Recorremos todos los items de entrada
const items = $input.all();
for (const item of items) {
  const msg = item.json && item.json.Mensaje;
  if (!msg) continue;

  const msgClean = limpiarTexto(msg);

  // Coincidencia flexible: uno contenido en el otro
  if (resp.includes(msgClean) || msgClean.includes(resp)) {
    return [{
      json: {
        resultado: item.json.Mensaje,
        id: item.json.id || null
      }
    }];
  }
}

// Si no hay coincidencias
return [{ json: { resultado: null, motivo: 'No hubo coincidencia' } }];

// Normalizar burbujas - guardrail deterministico (H6 + P1) + body seguro.
// FAIL-OPEN: ante cualquier problema devuelve las partes originales sin modificar.
const subscriberId = $('Webhook').first().json.body.id;
const content = ($json && $json.message && $json.message.content) ? $json.message.content : ($json || {});

const crudas = [content.parte1, content.parte2, content.parte3]
  .map(p => (p == null ? '' : String(p)))
  .map(p => p.replace(/\*/g, '').trim());

function body(partes) {
  const utiles = partes.filter(p => p && p.length > 0);
  return { subscriber_id: subscriberId,
           fields: utiles.map((v, i) => ({ field_name: 'parte' + (i + 1), field_value: v })) };
}

let salida;
try {
  let nombre = '';
  try {
    const lead = $('Buscar si ya existe').first().json;
    nombre = String((lead && lead.Nombre) || '').trim().split(' ')[0];
  } catch (e) { nombre = ''; }

  // H6 - se conserva la PRIMERA oracion interrogativa y se descartan las siguientes
  let vistas = 0;
  const unaPregunta = crudas.map(parte => {
    if (!parte) return '';
    const oraciones = parte.match(/[^.!?]+[.!?]*/g) || [parte];
    const out = [];
    for (const o of oraciones) {
      if (o.indexOf('?') !== -1) { vistas++; if (vistas > 1) continue; }
      out.push(o);
    }
    return out.join('').replace(/\s+/g, ' ').trim();
  });

  // P1 - el nombre del lead aparece como maximo una vez
  let usos = 0;
  const sinRepetir = unaPregunta.map(parte => {
    if (!parte || !nombre || nombre.length < 3) return parte;
    const re = new RegExp('\\b' + nombre.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'gi');
    return parte.replace(re, m => { usos++; return usos === 1 ? m : ''; })
      .replace(/\s+([,.!?])/g, '$1')
      .replace(/,\s*([.!?])/g, '$1')
      .replace(/\s*,\s*,/g, ',')
      .replace(/\s{2,}/g, ' ')
      .replace(/^[\s,]+/, '')
      .replace(/[\s,]+$/, '')
      .trim();
  }).map(p => (p ? p.charAt(0).toUpperCase() + p.slice(1) : p));

  const finales = sinRepetir.filter(p => p && p.length > 0);
  if (finales.length === 0) throw new Error('quedaron 0 partes');
  salida = { mcBody: body(finales), preguntas: Math.min(vistas, 1),
             partes: finales.length, texto: finales.join('\n\n'), fallback: false };
} catch (e) {
  salida = { mcBody: body(crudas), preguntas: null, partes: crudas.filter(Boolean).length,
             texto: crudas.filter(Boolean).join('\n\n'), fallback: true, motivo: String(e.message || e) };
}

return [{ json: salida }];
